+      long start = gkyl_range_idx(&range, idx);
+      const double *fptr = (const double *)gkyl_array_cfetch(inp, start);
+      f = fabs(fptr[k]);
+    }
+    double bResult = BlockReduceT(temp).Reduce(
+      f,
+#if CUDART_VERSION > 12090
+      ::cuda::std::plus()
+#else
+      cub::Sum()
+#endif
+    );
+    if (threadIdx.x == 0) {
+      atomicAdd(&out[k], bResult);
+    }
+  }
