#include <gkyl_gyrokinetic_multib_priv.h>

typedef void (*write_fdot_func_t)(
  struct gkyl_gyrokinetic_multib_app *app, struct gkyl_array *fout[]
);

static void
write_fdot_enabled(struct gkyl_gyrokinetic_multib_app *app, struct gkyl_array *fout[])
{
  for (int b = 0; b < app->num_local_blocks; ++b) {
    struct gkyl_gyrokinetic_app *sbapp = app->singleb_apps[b];
    int li_charged = b * app->num_species;
    for (int i = 0; i < app->num_species; ++i) {
      gk_species_write_fdot(sbapp, &sbapp->species[i], fout[li_charged + i]);
    }
  }
}

static void
write_fdot_disabled(struct gkyl_gyrokinetic_multib_app *app, struct gkyl_array *fout[])
{
  // Do nothing.
}

static void
gyrokinetic_multib_forward_euler(
  struct gkyl_gyrokinetic_multib_app *app, double tcurr, double dt, const struct gkyl_array *fin[],
  struct gkyl_array *fout[], struct gkyl_array **bflux_in[], struct gkyl_array **bflux_out[],
  const struct gkyl_array *fin_neut[], struct gkyl_array *fout_neut[],
  struct gkyl_array **bflux_in_neut[], struct gkyl_array **bflux_out_neut[],
  write_fdot_func_t write_fdot_func, struct gkyl_update_status *st
)
{
  struct timespec wst_fe = gkyl_wall_clock();
  // Take a forward Euler step with the suggested time-step dt. This may
  // not be the actual time-step taken. However, the function will never
  // take a time-step larger than dt even if it is allowed by
  // stability. The actual time-step and dt_suggested are returned in
  // the status object.
  app->stat.nfeuler += 1;

  double dtmin = DBL_MAX;

  // Compute the time rate of change of the distributions, df/dt.
  for (int b = 0; b < app->num_local_blocks; ++b) {
    int li_charged = b * app->num_species;
    int li_neut = b * app->num_neut_species;
    gyrokinetic_rhs(
      app->singleb_apps[b], tcurr, dt, &fin[li_charged], &fout[li_charged], &bflux_out[li_charged],
      &fin_neut[li_neut], &fout_neut[li_neut], &bflux_out_neut[li_neut], st
    );
    dtmin = fmin(dtmin, st->dt_actual);
  }

  struct timespec wtm = gkyl_wall_clock();
  // Compute minimum time-step across all processors.
  double dtmin_local = dtmin, dtmin_global;
  gkyl_comm_allreduce_host(app->comm, GKYL_DOUBLE, GKYL_MIN, 1, &dtmin_local, &dtmin_global);
  st->dt_actual = dtmin_global;
  app->stat.dfdt_dt_reduce_tm += gkyl_time_diff_now_sec(wtm);

  write_fdot_func(app, fout);

  struct timespec wst = gkyl_wall_clock();
  // Complete update of distribution functions.
  double dta = st->dt_actual;
  for (int b = 0; b < app->num_local_blocks; ++b) {
    struct gkyl_gyrokinetic_app *sbapp = app->singleb_apps[b];
    int li_charged = b * app->num_species;
    int li_neut = b * app->num_neut_species;
    for (int i = 0; i < app->num_species; ++i) {
      struct gk_species *gks = &sbapp->species[i];
      gk_species_step_f(gks, fout[li_charged + i], dta, fin[li_charged + i]);
      gk_species_bflux_step_f(
        sbapp, &gks->bflux, bflux_out[li_charged + i], 1.0, bflux_in[li_charged + i]
      );
    }
    for (int i = 0; i < app->num_neut_species; ++i) {
      struct gk_neut_species *gkns = &sbapp->neut_species[i];
      gk_neut_species_step_f(gkns, fout_neut[li_neut + i], dta, fin_neut[li_neut + i]);
      gk_neut_species_bflux_step_f(
        sbapp, &gkns->bflux, bflux_out_neut[li_neut + i], 1.0, bflux_in_neut[li_neut + i]
      );
    }
  }

